"""Thin HTTP client for the arena API. Every method returns the JSON the server sends."""

import os
import threading
import time
import uuid

import httpx

# Venue Wi-Fi drops. Retrying with the same move id makes the server return the reply it already
# gave instead of playing the move twice, so retries are safe even mid-negotiation.
MOVE_ID_HEADER = "X-Move-Id"
RETRY_STATUS = {429, 500, 502, 503, 504}
CALLS_PER_SECOND = 9  # the arena allows 10 per key; stay just below, across all threads
# A supplier's reply can take up to about a minute (its time does not count against your 60 s),
# and a call may wait for another call on the same session first: wait long enough for both.
TIMEOUT_S = 180.0
# Practice has a daily quota per team: every practice session start carries what is left in this
# header, and GET /v1/me tells where the team stands.
REMAINING_HEADER = "X-Practice-Remaining"
ME_PATH = "/me"
# A 429 with a short Retry-After is the per-second rate limit: wait and retry. Any other 429 (the
# practice quota, too many open sessions) does not go away by retrying.
MAX_RETRY_AFTER_S = 5


class ArenaError(Exception):
    def __init__(self, status: int, detail):
        super().__init__(f"HTTP {status}: {detail}")
        self.status, self.detail = status, detail


class ArenaClient:
    def __init__(
        self,
        base_url=None,
        api_key=None,
        *,
        retries=3,
        transport=None,
        timeout=TIMEOUT_S,
        rate=CALLS_PER_SECOND,
    ):
        base_url = (base_url or os.environ.get("ARENA_URL", "")).rstrip("/")
        if not base_url:
            raise ValueError("set ARENA_URL (e.g. https://…) or pass base_url")
        key = api_key or os.environ.get("ARENA_API_KEY")
        headers = {"X-API-Key": key} if key else {}
        self.retries, self.rate, self._lock, self._next = retries, rate, threading.Lock(), 0.0
        self.practice_remaining = None  # from the last practice reply that said so
        self.http = httpx.Client(base_url=f"{base_url}/v1", headers=headers, timeout=timeout, transport=transport)

    def _pace(self):
        with self._lock:
            now = time.monotonic()
            wait, self._next = self._next - now, max(now, self._next) + 1 / self.rate
        if wait > 0:
            time.sleep(wait)

    def _call(self, method, path, body=None, params=None, raw=False):
        headers = {MOVE_ID_HEADER: uuid.uuid4().hex} if method == "POST" else {}
        for attempt in range(self.retries + 1):
            self._pace()
            try:
                r = self.http.request(method, path, json=body, params=params, headers=headers)
            except httpx.TransportError:
                if attempt == self.retries:
                    raise
                wait = None
            else:
                wait = r.headers.get("Retry-After", "")
                short = wait.isdigit() and int(wait) <= MAX_RETRY_AFTER_S
                if r.status_code not in RETRY_STATUS or attempt == self.retries or (r.status_code == 429 and not short):
                    break
            time.sleep(float(wait) if wait and wait.isdigit() else 0.5 * 2**attempt)
        if (left := r.headers.get(REMAINING_HEADER, "")).isdigit():
            self.practice_remaining = int(left)
        if r.status_code >= 400:
            try:
                detail = r.json().get("detail", r.text)
            except (ValueError, AttributeError):
                detail = r.text
            raise ArenaError(r.status_code, detail)
        return r.content if raw else r.json()

    def register(self, team_name, event_code):
        """arena-sim only: the simulator hands out its own keys. On the arena, the organisers
        give each team its key."""
        return self._call("POST", "/register", {"team_name": team_name, "event_code": event_code})

    def me(self):
        """Your team: practice sessions used and left, when the quota resets, best score per case."""
        return self._call("GET", ME_PATH)

    def cases(self, set_="practice"):
        return self._call("GET", "/cases", params={"set": set_})

    def open_session(self, case_id):
        return self._call("POST", "/sessions", {"case_id": case_id})

    def send_message(self, session_id, supplier_id, message):
        """Your e-mail to one supplier; returns its reply (or the result, if `action` closes)."""
        path = f"/sessions/{session_id}/threads/{supplier_id}/messages"
        return self._call("POST", path, {"message": message})

    def thread(self, session_id, supplier_id):
        return self._call("GET", f"/sessions/{session_id}/threads/{supplier_id}")

    def attachment(self, session_id, attachment_id):
        """The bytes of a document a supplier attached."""
        return self._call("GET", f"/sessions/{session_id}/attachments/{attachment_id}", raw=True)

    def backoffice(self, session_id):
        return self._call("GET", f"/sessions/{session_id}/backoffice")

    def move(self, session_id, supplier_id, move):
        body = {"supplier_id": supplier_id, "move": move}
        return self._call("POST", f"/sessions/{session_id}/moves", body)

    def accept(self, session_id, offer_id):
        return self._call("POST", f"/sessions/{session_id}/accept", {"offer_id": offer_id})

    def walk_away(self, session_id):
        return self._call("POST", f"/sessions/{session_id}/walk_away")

    def session(self, session_id):
        return self._call("GET", f"/sessions/{session_id}")

    def sessions(self, set_="practice"):
        return self._call("GET", "/sessions", params={"set": set_})

    def leaderboard(self, set_="practice"):
        return self._call("GET", "/leaderboard", params={"set": set_})

    def downloads(self):
        """The data you can download: the package, and the Sunday release once it is public."""
        return self._call("GET", "/data")

    def download(self, name):
        """A data download (zip bytes), e.g. "package" or "release-sunday"."""
        return self._call("GET", f"/data/{name}.zip", raw=True)
"""Contract tests: the kit's client and both example agents against arena-sim over HTTP - and
against a hosted arena when ARENA_TEST_URL and ARENA_TEST_KEY are set."""

import json
import os
import secrets
import sys
import time

import httpx
import pytest

from arena_kit import ArenaClient, ArenaError, RemoteTable, play, play_all
from arena_kit.agents import LLMAgent, NaiveAgent
from arena_kit.docs import quote_terms
from arena_kit.play import fetch_documents, play_waves

RESULT = {"ended", "deal", "supplier_id", "offer_id", "terms", "c_open", "c_deal", "c_best", "score"}


def team(url, code="sim"):
    key = ArenaClient(url).register(f"test-{secrets.token_hex(3)}", code)["api_key"]
    return ArenaClient(url, key, rate=1000)


def scripted(system, user):
    """A stand-in model: lowballs on the first live thread, accepts once the supplier stops."""
    sid = ":".join(user.split("THREAD ")[1].split(":")[:2])
    stop = any(f"status {s}" in user for s in ("final_offer", "agreed"))
    if stop or user.count("--- buyer") >= 8:
        return json.dumps({"supplier_id": sid, "action": "accept"})
    body = "Thank you. Could you send a cost breakdown?"
    return json.dumps({"supplier_id": sid, "action": "send", "body": body, "term_sheets": [{"unit_price": 1.0}]})


@pytest.fixture(params=["sim", "hosted"])
def arena(request):
    if request.param == "hosted":
        url, key = os.environ.get("ARENA_TEST_URL"), os.environ.get("ARENA_TEST_KEY")
        if not (url and key):
            pytest.skip("set ARENA_TEST_URL and ARENA_TEST_KEY to run against a hosted arena")
        return ArenaClient(url, key), 1
    url, _, _ = request.getfixturevalue("sim")
    return team(url), 3


def test_both_agents_play_unchanged(arena):
    client, n = arena
    for case in client.cases("practice")[:n]:
        for agent in (NaiveAgent(), LLMAgent(scripted)):
            result = play(RemoteTable(client), case["case_id"], agent)
            assert RESULT <= set(result) and result["ended"]
            assert result["score"] is None or 0 <= result["score"] <= 1


def test_naive_is_deterministic_and_play_all_runs_in_parallel(sim):
    client = team(sim[0])
    ids = [c["case_id"] for c in client.cases()]
    first = play_all(lambda: RemoteTable(client), ids + ["case:NOPE"], NaiveAgent)
    second = play_all(lambda: RemoteTable(client), ids, NaiveAgent)
    assert all(first[i] == second[i] and first[i]["deal"] for i in ids)
    assert isinstance(first["case:NOPE"], ArenaError) and first["case:NOPE"].status == 404


def test_documents_follow_the_arena_format(sim):
    client, table = team(sim[0]), None
    table = RemoteTable(client)
    case, threads = table.open("case:S03")
    sup, [opening] = next(iter(threads.items()))
    terms = quote_terms(fetch_documents(table, opening)["attachments"][0]["text"])
    assert terms["stated"] == opening["term_sheets"][0]["terms"]
    assert set(terms["standard"]) == set(opening["missing_fields"])
    assert terms["fixed"]["lead_time_days"] == case["fixed_terms"]["lead_time_days"]
    reply = table.send(sup, {"body": "Could you send a cost breakdown? (idx:NOPE@2026-01)", "term_sheets": []})
    assert reply["claim_results"] == [{"index": 0, "result": "contradicted"}]  # an ID the data lacks
    assert "=SUM(B2:B5)" in fetch_documents(table, reply)["attachments"][0]["text"]


def test_a_rival_quote_counts_once_per_supplier_the_rest_once_per_case(sim):
    url, state, _ = sim
    state.facts["quote:9001"] = {"unit_price": 100.0}  # a rival's quote the buyer holds
    table = RemoteTable(team(url))
    _, threads = table.open("case:S02")
    a, b = threads
    rival = threads[a][0]["term_sheets"][0]["term_sheet_id"]  # a's opening, an offer: ID

    def cite(sup, ids):
        reply = table.send(sup, {"body": f"Please consider {', '.join(ids)}.", "term_sheets": []})
        return [r["result"] for r in reply["claim_results"]]

    assert cite(a, ["quote:9001", "idx:PPI-C241@2026-08"]) == ["verified", "verified"]
    assert cite(b, ["quote:9001", "idx:PPI-C241@2026-08", rival]) == ["verified", "duplicate", "verified"]
    assert cite(b, ["quote:9001", rival, "idx:NOPE@2026-01"]) == ["duplicate", "duplicate", "contradicted"]
    assert cite(b, ["idx:NOPE@2026-01"]) == ["contradicted"]  # an unknown ID never becomes a duplicate

"""When to close (section 7), the accept ladder (R12.11) and the close guards of DualAgent and
TeamAgent (R11.17-R11.18, R12.12-R12.13, R12.15, R13.13). Pure functions over `View`s - one per live
supplier thread - so the rules are testable on recorded negotiations without the arena.

Accept the cheapest sheet that keeps the must-haves and beats the alternative when the supplier
agreed (R7.1), made a final offer (R7.2), its offer meets our next target - unless it is still
moving with more than 3 rounds left (R7.3) - its offer is as good as what we last offered (R7.4), at
most one round is left (R7.5), or the planned rounds are over (R7.6). Walk away only when nothing on
the table is acceptable and every thread is at a final offer or out of rounds. No deadlock close and
no walk-risk close.
"""

from dataclasses import dataclass, field

EARLIER_SHARE = 0.001  # R12.11: earlier IDs cheaper by 0.1 %+ go before the latest ones
MAX_EARLIER = 3
REVISIT_SHARE = 0.003  # R12.13: an earlier sheet 0.3 % cheaper is offered back once
COVERAGE_SHARE = 0.01  # R11.17: uncovered need over 1 % of C never "meets our target"
TARGET_TOL = 0.002  # R7.3
LAST_TOL = 0.001  # R7.4
MOVING_ROUNDS = 3  # R5.4 / R7.3
HOPELESS_SHARE, HOPELESS_MOVE = 0.08, 0.01  # R12.15
DEAR_SHARE = 0.25  # R8.2
STALL_TOL = 0.001


@dataclass
class Row:
    """One sheet the supplier put on the table: a main sheet or an alternative."""

    id: str
    terms: dict
    c: float  # our C with the margin charge where the goal has one
    valid: bool  # keeps the must-haves and beats the alternative
    latest: bool  # in its latest e-mail
    main: bool = True
    reply: int = 0  # which of its replies (0 = the opening)
    uncovered: float = 0.0  # EUR of uncovered need (and its risk) in C


@dataclass
class View:
    """One live supplier thread, as the close rules see it."""

    sid: str
    status: str | None
    left: int  # messages we may still send
    sent: int  # our messages that reached it
    rows: list = field(default_factory=list)
    target: float | None = None  # our next target C
    last_target: float | None = None  # the target of our last offer
    moving: bool = False  # still conceding more than 0.4 % of C (R5.4)
    only_price: bool = False  # every step term settled (R13.13)
    planned_over: bool = False  # H + 2 offers made (R7.6)
    close_gap: float = 0.005
    replies_c: list = field(default_factory=list)  # C of its best sheet per reply, oldest first
    earlier_used: bool = False  # R12.13 offer-back already made
    repair_used: bool = False  # R12.12 repair already made
    restore_used: bool = False  # R11.17 coverage message already made
    last_step_share: float = 0.0  # how far it moved in its last reply, share of C

    @property
    def latest_rows(self):
        return [r for r in self.rows if r.latest]

    @property
    def best(self):
        """Its cheapest valid sheet of the latest e-mail (R3.1), else None."""
        ok = [r for r in self.latest_rows if r.valid]
        return min(ok, key=lambda r: r.c) if ok else None

    @property
    def c_now(self):
        rows = self.latest_rows
        return min((r.c for r in rows if r.valid), default=min((r.c for r in rows), default=float("inf")))


@dataclass
class Close:
    kind: str  # accept | walk | idle | offer_back | repair | restore
    reason: str
    sid: str | None = None
    sheet_id: str | None = None
    candidates: list = field(default_factory=list)  # the accept ladder [(sid, sheet_id)]
    terms: dict | None = None  # offer_back / repair / restore: the terms to send


def blocked(views, row, sid):
    """R11.18: never accept a bidder's unchanged opening while a cheaper rival sheet is on the table."""
    if row.reply != 0 or len(views) < 2:
        return False
    return any(r.valid and r.latest and r.c < row.c for v in views.values() if v.sid != sid for r in v.rows)


def ladder(views):
    """R12.11: every valid sheet ever offered in every live thread, cheapest first; up to MAX_EARLIER
    earlier IDs (cheaper by EARLIER_SHARE+) before the latest ones. A refused accept changes nothing."""
    rows = sorted(
        (r.c, not r.latest, not r.main, v.sid, r.id)
        for v in views.values()
        for r in v.rows
        if r.valid and not blocked(views, r, v.sid)
    )
    now = [x for x in rows if not x[1]]
    if not now:
        return []
    earlier = [x for x in rows if x[1] and x[0] < now[0][0] * (1 - EARLIER_SHARE)][:MAX_EARLIER]
    return list(dict.fromkeys((x[3], x[4]) for x in sorted(earlier + now)))


def accept(views, reason):
    cands = ladder(views)
    if not cands:
        return None
    return Close("accept", reason, cands[0][0], cands[0][1], cands)


def walk(views, reason):
    sid = next(iter(views)) if views else None
    return Close("walk", reason, sid)


def earlier_cheaper(view):
    """R12.13: once per thread, an earlier valid sheet of its own 0.3 % cheaper than the best of its
    latest e-mail - its terms go back as our sheet."""
    if view.earlier_used or view.left <= 0 or view.status == "final_offer":
        return None
    now = [r.c for r in view.latest_rows if r.valid] or [r.c for r in view.latest_rows]
    before = [r for r in view.rows if not r.latest and r.valid]
    if not now or not before:
        return None
    r = min(before, key=lambda r: r.c)
    return r if r.c <= (1 - REVISIT_SHARE) * min(now) else None


def stalled(view):
    """No cheaper offer over its last three replies after 3+ of our messages (R12.13)."""
    cs = view.replies_c
    if view.sent < 3 or len(cs) < 3:
        return False
    return cs[-1] >= cs[-3] - max(1.0, STALL_TOL * cs[-3])


def covered(view, row):
    return row is not None and row.uncovered <= COVERAGE_SHARE * row.c


def ends(view):
    """At a final offer or out of rounds: nothing more will come from this thread."""
    return view.status in ("final_offer", "agreed") or view.left <= 0


def hopeless(views, view):
    """R12.15 / R8.2 (RFQ, 3+ live bidders): far dearer than the best and not moving - stop writing."""
    if len(views) < 3 or view.best is None:
        return False
    best_all = min((v.best.c for v in views.values() if v.best), default=None)
    if best_all is None:
        return False
    if (
        view.best.c > (1 + HOPELESS_SHARE) * best_all
        and view.last_step_share < HOPELESS_MOVE
        and len(view.replies_c) >= 3
    ):
        return True
    return view.best.c > (1 + DEAR_SHARE) * best_all and view.sent >= 2


def decide(views, sid, must_close=False):
    """The close rule for thread `sid`, or None (negotiate on). `views`: every live thread."""
    v = views[sid]
    rfq = len(views) > 1
    cands = ladder(views)
    best_sid = cands[0][0] if cands else None
    heard = all(x.sent >= 1 for x in views.values())  # R11.18: every bidder has had an offer
    may_accept = bool(cands) and (not rfq or heard)

    if must_close:  # R11.14: closed by the clock
        return accept(views, "case clock: close") or walk(views, "case clock: nothing acceptable")

    if v.status == "final_offer":  # R12.12: its last word - accept at once, anything more makes it walk
        if cands and (not rfq or best_sid == sid or all(ends(x) for x in views.values())):
            return accept(views, "final offer")
        if cands and rfq:
            return Close("idle", "final offer, a rival is better", sid)
        if not v.repair_used and v.left > 0 and v.rows:
            return Close("repair", "final offer breaks a must-have or loses to the alternative - one repair", sid)
        if all(ends(x) for x in views.values()):
            return walk(views, "nothing acceptable, every thread at its end")
        return Close("idle", "final offer, nothing acceptable here", sid)

    if v.status == "agreed":  # R7.1, R12.13
        if (r := earlier_cheaper(v)) is not None:
            return Close("offer_back", "its earlier offer was cheaper than the agreed sheet", sid, r.id, terms=r.terms)
        if may_accept and (not rfq or best_sid == sid):
            return accept(views, "agreed to our terms")

    if stalled(v):  # R12.13: back to its earlier, cheaper offer once - never a deadlock close (R5.3, R7)
        if (r := earlier_cheaper(v)) is not None:
            return Close("offer_back", "stalled: back to its own earlier, cheaper offer", sid, r.id, terms=r.terms)

    best = v.best
    if best is not None and v.sent >= 1 and v.target is not None:
        meets = best.c <= v.target * (1 + TARGET_TOL) and not (v.moving and v.left > MOVING_ROUNDS)
        if meets and not covered(v, best):  # R11.17
            if v.left > 0 and not v.restore_used:
                return Close("restore", "meets the target but leaves need uncovered", sid, best.id, terms=best.terms)
            meets = False
        if meets and may_accept and best_sid == sid:
            return accept(views, "its offer meets our next target")
        if (
            v.only_price
            and best.c <= v.target * (1 + v.close_gap)
            and covered(v, best)
            and may_accept
            and best_sid == sid
        ):
            return accept(views, "small gap, only price left")  # R13.13
    if best is not None and v.last_target is not None and best.c <= v.last_target * (1 + LAST_TOL):
        if covered(v, best) and may_accept and best_sid == sid:
            return accept(views, "its offer is as good as what we last offered")  # R7.4

    if (v.left <= 1 and not rfq) or all(x.left <= 1 for x in views.values()):  # R7.5
        if may_accept or (cands and rfq):
            return accept(views, "at most one round left")
        if all(ends(x) for x in views.values()):
            return walk(views, "nothing acceptable and no rounds left")
    if all(x.planned_over for x in views.values()) and may_accept:  # R7.6
        return accept(views, "the planned rounds are over")
    if rfq and hopeless(views, v):
        return Close("idle", "far dearer than the best bidder and not moving", sid)
    if v.left <= 0:
        return (
            Close("idle", "no messages left in this thread", sid)
            if rfq
            else (accept(views, "no messages left") or walk(views, "no messages left, nothing acceptable"))
        )
    return None
