    price - a real, valid offer rather than an empty e-mail."""
    t = complete(ctx.case, {**base, "unit_price": round(0.995 * ctx.their_price, 2)}, ctx.std)
    return [("their terms", t)] if ctx.ok(t) and t["unit_price"] < ctx.their_price else []


